    23	        const batch = await framesAfter(c.ws, c.sent);
    24	        if (!batch.length) break;
    25	        for (const f of batch) c.socket.send(JSON.stringify(f));
    26	        c.sent = batch[batch.length - 1].seq;
    27	      }
    28	    } while (c.again);
    29	  } catch (e) {
    30	    console.error('ws flush failed', e);
    31	  } finally {
    32	    c.busy = false;
    33	  }
